  if (!trimmed) return null;

  const separator = trimmed.indexOf(',');

  if (separator === -1) return { address: null, name: trimmed };

  const name = trimmed.slice(0, separator).trim();
  const address = trimmed.slice(separator + 1).trim();

  // A leading comma leaves no name. The whole line is then the address, and
  // promoting it to the name keeps the section from rendering an empty heading.
  if (!name) return { address: null, name: address };

  return { address: address || null, name };
